  assert.equal(zero.refusals.length, 2);
  zero.refusals.forEach((item, index) =>
    refusal(item, emptyGrammarFixturePins.zeroRefusals[index], 'ps'));
  return { receiptField: 'grammar', observationsSha256: hash(JSON.stringify(value)),
